//! Generated by tpt-dev-codec's examples/schema_codegen.rs from the sensor schema.
//! Do not edit by hand: rerun the example to regenerate.

#![allow(clippy::unwrap_used, clippy::panic, dead_code, unreachable_pub)]

#[path = "../examples/generated/sensor.rs"]
mod sensor;

const MAX: [u64; 4] = [255, 4095, 15, 65535];
const EXAMPLE: &str = "id=7 temp=300 flags=3 seq=65535";
const BYTES: usize = 5;

#[test]
fn maximum_values_round_trip_through_the_layout() {
    let bytes = sensor::encode(&MAX).unwrap();
    assert_eq!(sensor::decode(&bytes).unwrap(), MAX);
}

#[test]
fn each_field_at_its_maximum_round_trips_alone() {
    for i in 0..sensor::FIELD_COUNT {
        let mut values = [0u64; sensor::FIELD_COUNT];
        values[i] = MAX[i];
        let bytes = sensor::encode(&values).unwrap();
        assert_eq!(
            sensor::decode(&bytes).unwrap(),
            values,
            "field {}",
            sensor::FIELD_NAMES[i]
        );
    }
}

#[test]
fn text_parses_to_the_values_the_codec_expects() {
    assert_eq!(
        sensor::parse(EXAMPLE.as_bytes()).unwrap(),
        [7, 300, 3, 65535]
    );
}

#[test]
fn chunked_text_parses_the_same_as_whole_text() {
    let bytes = EXAMPLE.as_bytes();
    let whole = sensor::parse(bytes).unwrap();
    let one_byte: Vec<&[u8]> = bytes.chunks(1).collect();
    assert_eq!(sensor::parse_chunks(&one_byte).unwrap(), whole);
    let uneven: Vec<&[u8]> = bytes.chunks(5).collect();
    assert_eq!(sensor::parse_chunks(&uneven).unwrap(), whole);
}

#[test]
fn parsed_text_encodes_and_decodes_unchanged() {
    let values = sensor::parse(EXAMPLE.as_bytes()).unwrap();
    let bytes = sensor::encode(&values).unwrap();
    assert_eq!(sensor::decode(&bytes).unwrap(), values);
}

#[test]
fn values_wider_than_their_field_are_refused_by_both_paths() {
    for i in 0..sensor::FIELD_COUNT {
        let mut values = [0u64; sensor::FIELD_COUNT];
        values[i] = MAX[i] + 1;
        assert!(
            sensor::encode(&values).is_err(),
            "encode accepted field {}",
            sensor::FIELD_NAMES[i]
        );
    }
    let too_big = "id=256 temp=300 flags=3 seq=65535";
    assert_eq!(
        sensor::parse(too_big.as_bytes()),
        Err(sensor::ParseFail::OutOfRange { field: "id" })
    );
}

#[test]
fn malformed_text_is_refused() {
    let cases = [
        "",
        "id=7 temp=300 flags=3",
        "id=7 temp=300 seq=65535 flags=3",
        "id= temp=300 flags=3 seq=65535",
        "id=7 temp=300 flags=3 seq=65535 extra=1",
        "id=7 temp=300 flags=3 seq=6x",
    ];
    for case in cases {
        assert!(sensor::parse(case.as_bytes()).is_err(), "accepted {case:?}");
    }
}
